mapper.select:
SELECT te.id, te.title, te.row_count, te.session_id, te.create_time
FROM table_export te


        te.session_id = #{sessionId}


        AND EXISTS (
            SELECT 1 FROM user_session us
            WHERE us.session_id = te.session_id AND us.user_id = #{userId}
        )


ORDER BY te.create_time DESC

SELECT id, title, row_count, session_id, create_time
FROM table_export
WHERE id = #{id}

